// Recibe respuesta de Buscar contacto por tel (voz). Extrae lead_id activo.
// Conserva todos los campos del Edit Fields Retell upstream.
const ef = $('Edit Fields Retell').item.json;
const contactsResp = $input.all().map(i => i.json);

let leadId = ef.Lead_id || null;
let contactId = ef.contac_id || null;

// Si Retell envió Lead_id explícito, respetarlo.
if (leadId) {
  return [{ json: { ...ef, Lead_id: leadId, contac_id: contactId } }];
}

// Si no, buscar en la respuesta Kommo por teléfono.
for (const r of contactsResp) {
  const contacts = r?._embedded?.contacts || [];
  for (const c of contacts) {
    if (!contactId) contactId = c.id;
    const leads = c?._embedded?.leads || [];
    if (leads.length > 0) {
      // Tomar el primer lead. (Mejorable: filtrar por status activo.)
      leadId = leads[0].id;
      contactId = c.id;
      break;
    }
  }
  if (leadId) break;
}

return [{ json: { ...ef, Lead_id: leadId, contac_id: contactId } }];

const calc = $('Calc fechas cambio').item.json;
const resp = $input.first().json;
const lead = (resp && resp._embedded && resp._embedded.leads && resp._embedded.leads[0]) ? resp._embedded.leads[0] : resp;
const cf = Array.isArray(lead && lead.custom_fields_values) ? lead.custom_fields_values : [];
const byId = (id) => { const f = cf.find(x => x && x.field_id === id); return (f && f.values && f.values[0]) ? (f.values[0].value ?? null) : null; };
return [{ json: { ...calc, idealista_id: byId(1373305) || '', vivienda_direccion: byId(1373349) || '' } }];

const items = $input.all();
const borrado = items.some(i => i.json && i.json.success === true);
// 12-sep-2026: el leadId salia SOLO de parsear "Lead ID:" en la descripcion de los eventos que
// devuelven los nodos "Buscar <agente>". La ruta rapida (Eliminar Directo Rapido) no pasa por
// ninguno de ellos, asi que leadId quedaba null, el IF de cerrar tarea no disparaba y el
// sub-workflow terminaba sin salida -> la tool del chatbot recibia "did not return a response".
let leadId = null;
try { leadId = $('Resolver Lead Id Cancelacion').first().json.Lead_id || null; } catch (e) {}
if (!leadId) {
  const buscarNodes = ['Buscar evento en calendario','Buscar Ainhoa','Buscar Carlos','Buscar Pedro','Buscar Ramon','Buscar Elisa','Buscar Javier','Buscar Monica','Buscar Ramon Simarro'];
  for (const nodeName of buscarNodes) {
    try {
      const found = $(nodeName).all().find(i => i.json && i.json.description);
      if (found) {
        const m = String(found.json.description).match(/Lead ID:\s*(\d+)/);
        if (m) { leadId = m[1]; break; }
      }
    } catch (e) {}
  }
}
const mensaje = borrado
  ? 'Cita cancelada correctamente'
  : 'No he encontrado ninguna visita con esos datos. Puedes confirmarme el nombre o telefono con el que reservaste?';
return [{ json: { borrado, mensaje, leadId } }];

let leadId = null;
try { leadId = $('Edit Fields').item.json.Lead_id; } catch (e) {}
if (!leadId) { try { leadId = $('Extraer Lead_id (voz)').item.json.Lead_id; } catch (e) {} }
return [{ json: { Lead_id: leadId } }];

let lead = $input.first().json;
lead = (lead && lead.data !== undefined) ? lead.data : lead;
if (typeof lead === 'string') { try { lead = JSON.parse(lead); } catch (e) { lead = {}; } }
const cf = {};
for (const c of (lead.custom_fields_values || [])) cf[c.field_id] = (c.values || [])[0]?.value;
const calendarId = cf[1379550] || null;
const eventId = cf[1379552] || null;
const tieneInfo = !!(calendarId && eventId);
return [{ json: { calendarId, eventId, tieneInfo } }];

// Cascada de calendario del cambio de hora (12-sep-2026).
// El evento vive donde lo dejo la reserva, y ese dato exacto esta en el lead (1379550).
// Antes solo se miraba resolve_property_calendar(idealista_id): un lead sin referencia -- los que
// crea Calendario_a_Kommo desde las agendas -- caia al calendario general y la visita cambiada
// aparecia fuera de la agenda de su agente (caso Blanca / Elisa, 10-sep).
const GENERAL = 'consultingsimarroproperties@gmail.com';
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

const calc = $('Calc fechas cambio').first().json;
const ext = $('Extraer vivienda').first().json;

let leadResp = $('Get lead (cambio)').first().json;
const lead = (leadResp && leadResp._embedded && leadResp._embedded.leads && leadResp._embedded.leads[0])
  ? leadResp._embedded.leads[0] : leadResp;
const cf = {};
for (const c of ((lead && lead.custom_fields_values) || [])) cf[c.field_id] = ((c.values || [])[0] || {}).value;

const calGuardado = cf[1379550] || '';
const eventGuardado = cf[1379552] || '';
const agenteLead = cf[1373105] || '';

// Segundo recurso: el agente asignado del lead contra la tabla agents (Sync_agentes_calendar).
// Match por tokens: el enum de Kommo ("Carlos", "Ramon Sanchez Simarro") no es identico al
// agent_key ni al display_name, pero sus palabras si estan contenidas en ellos.
const agentes = $input.all().map(i => i.json).filter(a => a && a.calendar_id);
let calAgente = '';
if (agenteLead) {
  const toks = norm(agenteLead).split(' ').filter(Boolean);
  const hits = agentes.filter(a => {
    const set = new Set((norm(a.agent_key) + ' ' + norm(a.display_name)).split(' ').filter(Boolean));
    return toks.length > 0 && toks.every(t => set.has(t));
  });
  if (hits.length === 1) calAgente = hits[0].calendar_id;
}

let calRpc = '';
try {
  const r = $('Resolve cal (cambio)').first().json;
  const o = (r && typeof r.data === 'string') ? JSON.parse(r.data) : r;
  if (o && o.source === 'agent' && o.calendar_id) calRpc = o.calendar_id;
} catch (e) {}

const cal_destino = calGuardado || calAgente || calRpc || GENERAL;
return [{ json: {
  cal_destino,
  cal_viejo: calGuardado || cal_destino,
  event_viejo: eventGuardado,
  origen: calGuardado ? 'lead' : (calAgente ? 'agente' : (calRpc ? 'vivienda' : 'general')),
  lead_id: calc.Lead_id,
  idealista_id: ext.idealista_id || '',
  fechaInicioISO: calc.fechaInicioISO,
}}];

// Recheck del hueco nuevo antes de mover nada (12-sep-2026). La reserva ya lo hacia
// (Recheck Get WA / Calc Validar WA); el cambio de hora borraba y creaba a ciegas.
// El evento que se va a mover se excluye: si no, la propia visita del cliente bloquea
// su nueva hora por el buffer de 60 min entre viviendas distintas.
const cal = $('Cal destino (cambio)').first().json;
const calc = $('Calc fechas cambio').first().json;
const viejo = String(cal.event_viejo || '');
const leadId = String(calc.Lead_id || '');
const eventos = $input.all().map(i => i.json)
  .filter(e => e && e.start)
  .filter(e => !viejo || String(e.id || '') !== viejo)
  .filter(e => !(leadId && String(e.description || '').includes('Lead ID: ' + leadId)));
return [{ json: { modo: 'validar', start: calc.fechaInicioISO, idealista_id: String(cal.idealista_id || ''), eventos } }];

const P = (x) => { try { return (x && typeof x.data === 'string') ? JSON.parse(x.data) : (x || {}); } catch (e) { return {}; } };
const r = P($input.first() ? $input.first().json : {});
const tasks = ((r._embedded || {}).tasks) || [];
// Solo la tarea de visita (Meeting, task_type_id 2) y sin cerrar; la mas proxima si hay varias.
const visitas = tasks.filter(t => t && Number(t.task_type_id) === 2 && !t.is_completed)
  .sort((a, b) => Number(a.complete_till || 0) - Number(b.complete_till || 0));
return [{ json: { task_id: visitas.length ? visitas[0].id : null, encontradas: visitas.length } }];

