return [{ json: { task_id: visitas.length ? visitas[0].id : null, encontradas: visitas.length } }];

let leadId = '';
try { leadId = String($('Resolver Lead Id Cancelacion').first().json.Lead_id || ''); } catch (e) {}
if (!leadId || !/^\d+$/.test(leadId)) return [];
