const leadId = String(calc.Lead_id || '');
const eventos = $input.all().map(i => i.json)
  .filter(e => e && e.start)
  .filter(e => !viejo || String(e.id || '') !== viejo)
  .filter(e => !(leadId && String(e.description || '').includes('Lead ID: ' + leadId)));
return [{ json: { modo: 'validar', start: calc.fechaInicioISO, idealista_id: String(cal.idealista_id || ''), eventos } }];

